#!/usr/bin/env python3
"""Driver for filter/sort/fuzzy exploration. Unique names prefixed fsf_."""
import os, sys, shutil, sqlite3, subprocess, time

EXE = "/workspace/executable"
TPL = "/tmp/ed_tpl/entries.db"


def sh(*a, **kw):
    return subprocess.run(a, capture_output=True, text=True, **kw)


def seed(name, rows, config=None):
    """rows: list of (id,title,date,content,priority,[tags])"""
    home = f"/tmp/h_fsf_{name}"
    if os.path.isdir(home):
        shutil.rmtree(home)
    os.makedirs(home + "/tui-journal", exist_ok=True)
    shutil.copy(TPL, home + "/tui-journal/entries.db")
    c = sqlite3.connect(home + "/tui-journal/entries.db")
    c.execute("delete from entries")
    c.execute("delete from tags")
    for r in rows:
        eid, title, date, content, prio, tags = r
        c.execute("insert into entries (id,title,date,content,priority) values (?,?,?,?,?)",
                  (eid, title, date, content, prio))
        for t in tags:
            c.execute("insert into tags (entry_id,tag) values (?,?)", (eid, t))
    c.commit(); c.close()
    if config is not None:
        os.makedirs(home + "/.config/tui-journal", exist_ok=True)
        open(home + "/.config/tui-journal/config.toml", "w").write(config)
    return home


class T:
    def __init__(self, name, home=None, cols=120, rows=40, args="", env=None):
        self.sess = "fsf_" + name
        self.home = home or f"/tmp/h_fsf_{name}"
        os.makedirs(self.home, exist_ok=True)
        sh("tmux", "kill-session", "-t", self.sess)
        e = {"HOME": self.home, "TERM": "xterm-256color"}
        if env:
            e.update(env)
        parts = ["env", "-u", "NO_COLOR"] + [f"{k}={v!r}" for k, v in e.items()]
        cmd = " ".join(parts) + f" {EXE} {args}; echo __TJEXIT_$?__; sleep 900"
        sh("tmux", "new-session", "-d", "-s", self.sess, "-x", str(cols), "-y", str(rows), cmd)
        time.sleep(1.0)

    def send(self, k, delay=0.22):
        if k.startswith("^"):
            sh("tmux", "send-keys", "-t", self.sess, k[1:])
        else:
            sh("tmux", "send-keys", "-t", self.sess, "-l", k)
        time.sleep(delay)

    def keys(self, *ks, delay=0.22):
        for k in ks:
            self.send(k, delay)

    def cap(self, esc=False):
        a = ["tmux", "capture-pane", "-p", "-t", self.sess]
        if esc:
            a.insert(2, "-e")
        return sh(*a).stdout.rstrip("\n")

    def show(self, tag="", esc=False):
        print(f"===== {tag} =====")
        print(self.cap(esc=esc))
        print(f"===== /{tag} =====")

    def resize(self, cols, rows):
        sh("tmux", "resize-window", "-t", self.sess, "-x", str(cols), "-y", str(rows))
        time.sleep(0.6)

    def kill(self):
        sh("tmux", "kill-session", "-t", self.sess)


