    (1, "Alpha meeting notes", "2026-01-05T00:00:00+00:00", "content of alpha\nsecond line", 1, ["work", "urgent"]),
    (2, "beta shopping list", "2026-03-12T00:00:00+00:00", "milk eggs bread", 5, ["home"]),
    (3, "Gamma ray research", "2025-11-30T00:00:00+00:00", "physics stuff", None, ["work", "science"]),
    (4, "delta plan", "2026-08-01T00:00:00+00:00", "planning things", 3, []),
    (5, "Epsilon zzz", "2024-02-29T00:00:00+00:00", "old entry", 9, ["archive", "home"]),
]
